package io.wolftown.kaiku.testutil

/**
 * Loads golden JSON fixtures from `src/test/resources/golden/`.
 *
 * The files are generated by the server's own types
 * (`server/tests/integration/android_contract_fixtures.rs`) and must never be
 * edited by hand. Regenerate them with
 * `KAIKU_UPDATE_GOLDEN=1 SQLX_OFFLINE=true cargo test -p vc-server --test integration android_contract_fixtures`.
 */
object Golden {
    fun load(name: String): String {
        val resource = Golden::class.java.classLoader?.getResource("golden/$name")
            ?: error("Golden fixture golden/$name not found on the test classpath")
        return resource.readText()
    }
}
